create extension if not exists "pgcrypto";
create type public.subscription_status as enum ('active','expired','pending');
create type public.order_status as enum ('pending_verification','approved','rejected');
create table public.clients (id uuid primary key references auth.users(id) on delete cascade,name text not null,email text not null unique,subscription_status public.subscription_status not null default 'pending',slug text not null unique check (slug ~ '^[a-z0-9-]+$'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.card_profiles (id uuid primary key default gen_random_uuid(),client_id uuid not null unique references public.clients(id) on delete cascade,title text not null default '',company text not null default '',phone text not null default '',whatsapp text not null default '',email text not null default '',website text not null default '',linkedin text not null default '',instagram text not null default '',google_maps text not null default '',logo_url text not null default '',photo_url text,updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete cascade,status public.order_status not null default 'pending_verification',receipt_url text not null,created_at timestamptz not null default now());
create index orders_client_id_idx on public.orders(client_id);create index orders_status_idx on public.orders(status);create index clients_slug_idx on public.clients(slug);
alter table public.clients enable row level security;alter table public.card_profiles enable row level security;alter table public.orders enable row level security;
create policy "active profiles are public" on public.card_profiles for select using (exists(select 1 from public.clients c where c.id=client_id and c.subscription_status='active'));
create policy "clients read own account" on public.clients for select using (auth.uid()=id);create policy "clients update own account" on public.clients for update using (auth.uid()=id) with check (auth.uid()=id);
create policy "clients manage own profile" on public.card_profiles for all using (auth.uid()=client_id) with check (auth.uid()=client_id);
create policy "clients read own orders" on public.orders for select using (auth.uid()=client_id);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('profile-assets','profile-assets',true,10485760,array['image/png','image/jpeg','image/webp','image/svg+xml']),('payment-receipts','payment-receipts',false,10485760,array['image/png','image/jpeg','application/pdf']) on conflict(id) do nothing;
create policy "public profile assets" on storage.objects for select using(bucket_id='profile-assets');create policy "users upload profile assets" on storage.objects for insert to authenticated with check(bucket_id='profile-assets' and (storage.foldername(name))[1]=auth.uid()::text);create policy "users read own receipts" on storage.objects for select to authenticated using(bucket_id='payment-receipts' and (storage.foldername(name))[1]=auth.uid()::text);create policy "users upload own receipts" on storage.objects for insert to authenticated with check(bucket_id='payment-receipts' and (storage.foldername(name))[1]=auth.uid()::text);
